export class LicenseFamilies {
  /**
   * List license families
   *
   * Returns a cursor-paginated page of license families for the current organization, each with the version it currently resolves to: the family's default version, or its highest-numbered published version. A family whose versions are all drafts or all archived is still listed, with no current version.
   */
  public static listLicenseFamilies<ThrowOnError extends boolean = false>(
    options?: Options<ListLicenseFamiliesData, ThrowOnError>,
  ): RequestResult<ListLicenseFamiliesResponses, ListLicenseFamiliesErrors, ThrowOnError> {
    return (options?.client ?? client).get<
      ListLicenseFamiliesResponses,
      ListLicenseFamiliesErrors,
      ThrowOnError
    >({
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/license-families",
      ...options,
    });
  }

  /**
   * Get a license family by slug
   *
   * Resolves a license family to the version it currently serves, returned as currentVersion: the family's default version if it has one, otherwise its highest-numbered PUBLISHED version. This is the stable address for "the current version of this product", so a caller never has to name a version slug.
   *
   * A family with a default keeps serving it when a newer version is published -- the default is what the vendor puts forward, and superseding it is an explicit act (make another version the default, or unset it). A family without a default follows publication: the newest PUBLISHED version wins.
   *
   * Returns 404 GetLicenseFamily.NoPublishedVersion when the family exists but has no PUBLISHED version, since there is nothing to resolve to. Use ?include=versions to read such a family anyway: with the history requested, the family is returned with its versions and no currentVersion. Use ?version=N for explicit access to one version, including draft and archived ones.
   */
  public static getLicenseFamily<ThrowOnError extends boolean = false>(
    options: Options<GetLicenseFamilyData, ThrowOnError>,
  ): RequestResult<GetLicenseFamilyResponses, GetLicenseFamilyErrors, ThrowOnError> {
    return (options.client ?? client).get<
      GetLicenseFamilyResponses,
      GetLicenseFamilyErrors,
      ThrowOnError
    >({
      querySerializer: { parameters: { include: { array: { explode: false } } } },
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/license-families/{familySlug}",
      ...options,
    });
  }
}

