export class Notifications {
  /**
   * Read the caller's notification preferences
   *
   * Every notifiable event, with this user's effective value per channel: their own choice where they made one, the catalog default otherwise. Events absent from the catalog of an installation never appear, which is what keeps high-volume system events out of the feed.
   */
  public static getNotificationPreferences<ThrowOnError extends boolean = false>(
    options?: Options<GetNotificationPreferencesData, ThrowOnError>,
  ): RequestResult<
    GetNotificationPreferencesResponses,
    GetNotificationPreferencesErrors,
    ThrowOnError
  > {
    return (options?.client ?? client).get<
      GetNotificationPreferencesResponses,
      GetNotificationPreferencesErrors,
      ThrowOnError
    >({
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/v1/notification-preferences",
      ...options,
    });
  }

  /**
   * Set the caller's notification preferences
   *
   * Stores the signed-in user's choices and answers with the whole matrix. A value that equals the catalog default is stored as no row at all, so a later change to that default still reaches this user.
   */
  public static putNotificationPreferences<ThrowOnError extends boolean = false>(
    options: Options<PutNotificationPreferencesData, ThrowOnError>,
  ): RequestResult<
    PutNotificationPreferencesResponses,
    PutNotificationPreferencesErrors,
    ThrowOnError
  > {
    return (options.client ?? client).put<
      PutNotificationPreferencesResponses,
      PutNotificationPreferencesErrors,
      ThrowOnError
    >({
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/v1/notification-preferences",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });
  }

  /**
   * List the caller's notifications
   *
   * Returns the signed-in user's notification feed, newest first, with the unread count. Notifications are a view over this organization's audit trail, narrowed to the events the user subscribes to; the id of a notification is the id of the audit trail entry it reports.
   */
  public static listNotifications<ThrowOnError extends boolean = false>(
    options?: Options<ListNotificationsData, ThrowOnError>,
  ): RequestResult<ListNotificationsResponses, ListNotificationsErrors, ThrowOnError> {
    return (options?.client ?? client).get<
      ListNotificationsResponses,
      ListNotificationsErrors,
      ThrowOnError
    >({
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/v1/notifications",
      ...options,
    });
  }

  /**
   * Mark notifications read
   *
   * Marks the given notifications read for the signed-in user, or all of them with all: true. Ids belonging to another organization are ignored rather than rejected, so a retry of a partially applied call is safe.
   */
  public static markNotificationsRead<ThrowOnError extends boolean = false>(
    options: Options<MarkNotificationsReadData, ThrowOnError>,
  ): RequestResult<MarkNotificationsReadResponses, MarkNotificationsReadErrors, ThrowOnError> {
    return (options.client ?? client).post<
      MarkNotificationsReadResponses,
      MarkNotificationsReadErrors,
      ThrowOnError
    >({
      security: [
        {
          key: "bearerAuth",
          scheme: "bearer",
          type: "http",
        },
      ],
      url: "/v1/notifications/mark-read",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });
  }
}
